base='/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-19/alerts'
alerts_by_name=collections.defaultdict(list)
for f in sorted(glob.glob(os.path.join(base,'alerts_at_*.json'))):
    data=json.load(open(f))
    for a in data:
        if a.get('state')!='firing': continue
        ns=a['labels'].get('namespace')
        if ns!='otel-demo': continue
        alerts_by_name[a['labels']['alertname']].append(a)
print('Alert types:', list(alerts_by_name.keys()))
for name, lst in alerts_by_name.items():
    sample=lst[0]
    print('\n',name, 'count', len(lst))
    # show some fields
    for k in ['service','pod','container','severity']:
        if k in sample['labels']:
            print('  ',k, sample['labels'][k])
